extra_css:
/* parchment / leather with a soft vignette (fixed) */
:root.lia-variant-light .lia-canvas { background-image: url('embed:assets/parchment.svg'), radial-gradient(ellipse at center, transparent 55%, rgba(90, 60, 20, 0.22) 100%); background-attachment: fixed; }
:root.lia-variant-dark .lia-canvas { background-image: url('embed:assets/leather.svg'), radial-gradient(ellipse at center, transparent 50%, rgba(0, 0, 0, 0.45) 100%); background-attachment: fixed; }
.lia-header, .lia-toc, .lia-header .lia-support-menu--closed, .lia-header .lia-support-menu__nav, .lia-toc__search input { background-color: transparent; }
.lia-header { border-bottom: 3px double #c9a227; }
/* double ruled frame with an inner gold line, like a ruled manuscript page */
.lia-slide__content { border: 3px double rgba(139, 26, 26, 0.6); outline: 1px solid rgba(201, 162, 39, 0.7); outline-offset: -0.8rem; padding: 3.2rem 4rem; }
:root.lia-variant-dark .lia-slide__content { border-color: rgba(217, 178, 95, 0.55); }
/* rubricated titles with gold fleurons */
.lia-slide__content .h1 { text-shadow: 0.05em 0.05em 0 rgba(201, 162, 39, 0.55); }
.lia-slide__content .h1::before, .lia-slide__content .h1::after { content: '\2767'; color: #c9a227; font-family: serif; font-size: 0.6em; vertical-align: middle; margin: 0 0.6em; text-shadow: none; }
/* illuminated initial: lapis letter in a gold-ruled box */
.lia-slide__content > header + .lia-paragraph::first-letter { float: left; font-family: 'UnifrakturCook', serif; font-size: 4.4em; line-height: 0.82; color: #1e3f78; padding: 0.08em 0.14em 0; margin: 0.06em 0.18em 0 0; border: 2px solid #c9a227; background: rgba(201, 162, 39, 0.14); text-shadow: 0.04em 0.04em 0 rgba(201, 162, 39, 0.8); }
:root.lia-variant-dark .lia-slide__content > header + .lia-paragraph::first-letter { color: #d9b25f; background: rgba(217, 178, 95, 0.1); text-shadow: 0.04em 0.04em 0 rgba(139, 26, 26, 0.8); }
/* ornamental rule */
.lia-slide__content :is(hr, .lia-divider) { border: 0; height: auto; background: none; text-align: center; overflow: visible; }
.lia-slide__content :is(hr, .lia-divider)::after { content: '\2014 \2766 \2014'; color: #c9a227; font-size: 2rem; letter-spacing: 0.3em; }
/* marginalia-style quotes */
.lia-quote:not([class*='alert']) { background: transparent; border-left: 6px double #c9a227; padding-inline: 3rem; }
.lia-quote__text { font-size: 2.3rem; font-style: italic; }
/* gold underlines, gold-rimmed buttons and step markers */
.lia-link { text-decoration-color: #c9a227; text-decoration-thickness: 0.15rem; text-underline-offset: 0.2rem; }
.lia-btn:not(.lia-btn--transparent) { box-shadow: inset 0 0 0 1px rgba(201, 162, 39, 0.85); }
.lia-effect__circle { background-color: #c9a227; color: #2b1d0e; }
.lia-table__header { border-bottom: 3px double #c9a227; }
